def compute(vars):
    total_fair_value = vars["v1"] * vars["v2"]
    return {
        "value": total_fair_value,
        "trace": {
            "shares_thousands": vars["v1"],
            "fair_value_per_share": vars["v2"],
            "total_fair_value": total_fair_value,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": "dollars"
            }
        }
    }
